446    inline bool sanitize (hb_sanitize_context_t *c) const
   447    {
   448      TRACE_SANITIZE (this);
   449      if (!version.sanitize (c) || version < 2 ||
   450          !tableCount.sanitize (c))
   451        return_trace (false);
   452
   453      const KerxTable *table = &firstTable;
   454      unsigned int count = tableCount;
   455      for (unsigned int i = 0; i < count; i++)
   456      {
   457        if (!table->sanitize (c))
   458          return_trace (false);
   459        table = &StructAfter<KerxTable> (*table);
   460      }
   461
   462      return_trace (true);
   463    }
   464
   465    protected:
   466    HBUINT16      version;        /* The version number of the extended kerning table
   467                                   * (currently 2, 3, or 4). */
   468    HBUINT16      unused;         /* Set to 0. */
   469    HBUINT32      tableCount;     /* The number of subtables included in the extended kerning
   470                                   * table. */
   471    KerxTable     firstTable;     /* Subtables. */
   472  /*subtableGlyphCoverageArray*/  /* Only if version >= 3. We don't use. */
   473
